import{_ as r,o as a,c as e,a2 as n}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"Введение","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),o={name:"guide/getting-started.md"};function d(i,t,s,l,g,h){return a(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="введение" tabindex="-1">Введение <a class="header-anchor" href="#введение" aria-label="Permalink to &quot;Введение&quot;">​</a></h1><p><strong>можно.</strong> — это сервер фиче-флагов для команд любого размера.</p><p>С ним вы можете:</p><ul><li><strong>Включать и выключать фичи</strong> на продакшене без деплоя кода</li><li><strong>Раскатывать изменения постепенно</strong> — сначала 1% пользователей, потом 10%, потом всем</li><li><strong>Сегментировать аудиторию</strong> — показывать фичу только пользователям из определённой страны, с Premium-подпиской или на конкретном устройстве</li><li><strong>Проводить A/B-тесты</strong> с мультивариативными флагами</li><li><strong>Отслеживать все изменения</strong> через аудит-лог</li></ul><h2 id="как-это-работает" tabindex="-1">Как это работает <a class="header-anchor" href="#как-это-работает" aria-label="Permalink to &quot;Как это работает&quot;">​</a></h2><pre class="mermaid">graph LR
    A[Разработчик] --&gt;|Создаёт флаг| B[Веб-панель]
    B --&gt;|Сохраняет правила| C[Сервер можно.]
    D[SDK в приложении] --&gt;|Загружает правила| C
    D --&gt;|Оценивает флаг локально| E[Ваше приложение]
</pre><ol><li>Вы создаёте флаг в веб-панели и настраиваете правила: для каких пользователей, на каких окружениях, с каким процентом роллаута.</li><li>SDK в вашем приложении загружает правила с сервера один раз и кеширует их.</li><li>При каждом обращении к флагу SDK <strong>локально</strong> принимает решение — без задержек сети.</li><li>Если правила меняются, SDK получает обновление в фоне.</li></ol><h2 id="ключевые-понятия" tabindex="-1">Ключевые понятия <a class="header-anchor" href="#ключевые-понятия" aria-label="Permalink to &quot;Ключевые понятия&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Понятие</th><th>Описание</th></tr></thead><tbody><tr><td><strong>Флаг</strong></td><td>Именованная точка переключения в коде. Может быть булевой (вкл/выкл) или мультивариативной (A/B/C).</td></tr><tr><td><strong>Стратегия</strong></td><td>Способ раскатки флага: мгновенно, плавно, по расписанию, кастомная логика.</td></tr><tr><td><strong>Сегмент</strong></td><td>Переиспользуемая группа пользователей с общими правилами таргетинга.</td></tr><tr><td><strong>Контекст</strong></td><td>Атрибуты пользователя или запроса, по которым оцениваются правила флага.</td></tr><tr><td><strong>Окружение</strong></td><td>dev / staging / production — флаг может иметь разные настройки на каждом.</td></tr><tr><td><strong>API-ключ</strong></td><td>Ключ доступа SDK к серверу, привязанный к конкретному окружению.</td></tr></tbody></table><h2 id="готовы-попробовать" tabindex="-1">Готовы попробовать? <a class="header-anchor" href="#готовы-попробовать" aria-label="Permalink to &quot;Готовы попробовать?&quot;">​</a></h2><p>Переходите к <a href="/guide/quick-start.html">Быстрому старту</a> — запустите сервер за 5 минут.</p>`,11)])])}const p=r(o,[["render",d]]);export{u as __pageData,p as default};
